    if(rst) begin
        burststate <= idle; 
        burstcnt <= '0; 
        burstreg <= '0; 
        addr_reg <= '0; 
    end else begin 
        burststate <= burststate_nxt; 
        burstcnt <= burstcnt_nxt; 
        burstreg <= burstreg_next; 
        addr_reg <= addr_reg_nxt; 
    end
