logic read_active;
logic [ADDR_SIZE-1:0] active_addr;

always_comb begin
    bmem_addr    = addr_reg; 
    bmem_read    = 1'b0; 
    bmem_write   = 1'b0; 
    bmem_wdata   = '0;

    cache_rdata  = burstreg; 
    cache_resp   = 1'b0; 

    burststate_nxt = burststate; 
    burstcnt_nxt   = burstcnt; 
    burstreg_next  = burstreg; 
