module freelist
import rv32i_types::*;
(
    input logic clk, 
    input logic rst, 

    input rename2frlist_t rename2frlist,
    input commit2frlist_t commit2frlist, 

    output frlist2rename_t frlist2rename, 
    output logic frlist_full, 
    output logic frlist_empty, 

    input rob2frlist_t rob2frlist
);

    localparam int unsigned FL_DEPTH = (1 << PRF_IDX_WIDTH);
    localparam int unsigned FL_PTR_W  = PRF_IDX_WIDTH + 1;

    logic [PRF_IDX_WIDTH-1:0] fifo_mem [0:FL_DEPTH-1];
    logic [FL_PTR_W-1:0] head_q, head_d;
    logic [FL_PTR_W-1:0] tail_q, tail_d;

    logic pop_req, push_req;
    logic [PRF_IDX_WIDTH-1:0] push_data;
    logic [PRF_IDX_WIDTH-1:0] alloc_data;

    integer i;

    always_comb begin
        frlist_full  = ((tail_q[FL_PTR_W-2:0] == head_q[FL_PTR_W-2:0]) &&
                        (tail_q[FL_PTR_W-1]   != head_q[FL_PTR_W-1]));
        frlist_empty = (tail_q == head_q);

        alloc_data = fifo_mem[head_q[FL_PTR_W-2:0]];
        frlist2rename.pd = alloc_data;

        pop_req  = 1'b0;
        push_req = 1'b0;
        push_data = '0;

        if (rename2frlist.req && !frlist_empty) begin
            pop_req = 1'b1;
        end

        if (commit2frlist.valid) begin
            push_req  = 1'b1;
            push_data = commit2frlist.old_pdst;
        end
        else if (rob2frlist.valid) begin
            push_req  = 1'b1;
            push_data = rob2frlist.pdst;
        end

        head_d = head_q;
        tail_d = tail_q;

        if (pop_req)
            head_d = head_q + {{(FL_PTR_W-1){1'b0}}, 1'b1};

        if (push_req && !frlist_full)
            tail_d = tail_q + {{(FL_PTR_W-1){1'b0}}, 1'b1};
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            head_q <= '0;
            tail_q <= '0;
            for (i = 0; i < FL_DEPTH; i = i + 1) begin
