        do_free  = 1'b0;
        free_reg_in = '0;

        if (!frlist_empty && rename2frlist.req) begin
            do_alloc = 1'b1;
        end

        if (rob2frlist.valid) begin
            do_free = 1'b1;
            free_reg_in = rob2frlist.pd_old;
