                2'b01: begin
                    if (!frlist_full) begin
                        free_q[tail_ptr] <= free_reg_in;
                        tail_ptr <= tail_ptr + 1'b1;
                        count    <= count + 1'b1;
                    end
                end
                2'b11: begin
                    free_q[tail_ptr] <= free_reg_in;
                    tail_ptr <= tail_ptr + 1'b1;
                    head_ptr <= head_ptr + 1'b1;
                    count    <= count;
                end
