                free_q[tail_q] <= free_prd;
                head_q <= head_q + {{(PRF_IDX_WIDTH-1){1'b0}},1'b1};
                tail_q <= tail_q + {{(PRF_IDX_WIDTH-1){1'b0}},1'b1};
