        logic [31:0] mem_wdata;
        logic [3:0] mem_wmask;
        logic is_store;
        logic is_load;
        logic is_branch;
        logic is_jump;
        logic branch_taken;
        logic [31:0] branch_target;
        logic mispredict;
    } rob_entry_t;

    rob_entry_t rob_mem [0:ROB_DEPTH-1];

    logic [ROB_IDX_WIDTH-1:0] head_ptr, tail_ptr;
    logic [ROB_IDX_WIDTH:0]   count;

    integer i;

    function automatic logic idx_match(input logic [ROB_IDX_WIDTH-1:0] a, input logic [ROB_IDX_WIDTH-1:0] b);
        idx_match = (a == b);
    endfunction

    always_comb begin
        robempty = (count == '0);
        robfull  = (count == ROB_DEPTH);
        rob_idx_dispatch = tail_ptr;

        rob2commit = '0;
        rob2frlist = '0;

        if (!robempty && rob_mem[head_ptr].valid) begin
            rob2commit.valid         = rob_mem[head_ptr].ready;
            rob2commit.pc            = rob_mem[head_ptr].pc;
            rob2commit.inst          = rob_mem[head_ptr].inst;
            rob2commit.rd_arch       = rob_mem[head_ptr].rd_arch;
            rob2commit.rd_phy        = rob_mem[head_ptr].rd_phy;
            rob2commit.rd_we         = rob_mem[head_ptr].rd_we;
            rob2commit.result        = rob_mem[head_ptr].result;
            rob2commit.rs1_val       = rob_mem[head_ptr].rs1_val;
            rob2commit.rs2_val       = rob_mem[head_ptr].rs2_val;
            rob2commit.mem_addr      = rob_mem[head_ptr].mem_addr;
            rob2commit.mem_wdata     = rob_mem[head_ptr].mem_wdata;
            rob2commit.mem_wmask     = rob_mem[head_ptr].mem_wmask;
            rob2commit.is_store      = rob_mem[head_ptr].is_store;
            rob2commit.is_load       = rob_mem[head_ptr].is_load;
            rob2commit.is_branch     = rob_mem[head_ptr].is_branch;
            rob2commit.is_jump       = rob_mem[head_ptr].is_jump;
            rob2commit.branch_taken  = rob_mem[head_ptr].branch_taken;
            rob2commit.branch_target = rob_mem[head_ptr].branch_target;
            rob2commit.mispredict    = rob_mem[head_ptr].mispredict;
        end

        if (!robempty && rob_mem[head_ptr].valid && commit_ack) begin
            rob2frlist.valid   = rob_mem[head_ptr].rd_we;
            rob2frlist.prd_old = rob_mem[head_ptr].old_phy;
        end
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            head_ptr <= '0;
            tail_ptr <= '0;
            count    <= '0;
            for (i = 0; i < ROB_DEPTH; i = i + 1) begin
                rob_mem[i] <= '0;
            end
        end else begin
            if (branch_flush.flush) begin
                head_ptr <= '0;
                tail_ptr <= '0;
                count    <= '0;
                for (i = 0; i < ROB_DEPTH; i = i + 1) begin
                    rob_mem[i] <= '0;
                end
            end else begin
                if (common_data_bus.valid && idx_match(common_data_bus.rob_idx, head_ptr) && rob_mem[head_ptr].valid) begin
                    rob_mem[common_data_bus.rob_idx].ready  <= 1'b1;
                    rob_mem[common_data_bus.rob_idx].result <= common_data_bus.rd_v;
                end else if (common_data_bus.valid && rob_mem[common_data_bus.rob_idx].valid) begin
                    rob_mem[common_data_bus.rob_idx].ready  <= 1'b1;
                    rob_mem[common_data_bus.rob_idx].result <= common_data_bus.rd_v;
                end

                if (lsq2robpack.valid && rob_mem[lsq2robpack.rob_idx].valid) begin
                    rob_mem[lsq2robpack.rob_idx].ready     <= lsq2robpack.ready;
                    rob_mem[lsq2robpack.rob_idx].result    <= lsq2robpack.result;
                    rob_mem[lsq2robpack.rob_idx].mem_addr  <= lsq2robpack.mem_addr;
                    rob_mem[lsq2robpack.rob_idx].mem_wdata <= lsq2robpack.mem_wdata;
                    rob_mem[lsq2robpack.rob_idx].mem_wmask <= lsq2robpack.mem_wmask;
                end

                if (branchres2rob.valid && rob_mem[branchres2rob.rob_idx].valid) begin
                    rob_mem[branchres2rob.rob_idx].ready         <= 1'b1;
                    rob_mem[branchres2rob.rob_idx].branch_taken  <= branchres2rob.branch_taken;
                    rob_mem[branchres2rob.rob_idx].branch_target <= branchres2rob.branch_target;
                    rob_mem[branchres2rob.rob_idx].mispredict    <= branchres2rob.mispredict;
                    rob_mem[branchres2rob.rob_idx].result        <= branchres2rob.result;
                end

                if (jumpresrob.valid && rob_mem[jumpresrob.rob_idx].valid) begin
                    rob_mem[jumpresrob.rob_idx].ready         <= 1'b1;
                    rob_mem[jumpresrob.rob_idx].branch_taken  <= 1'b1;
                    rob_mem[jumpresrob.rob_idx].branch_target <= jumpresrob.target_pc;
                    rob_mem[jumpresrob.rob_idx].result        <= jumpresrob.result;
                end

                if (dispatch_2_rob.valid && !robfull) begin
                    rob_mem[tail_ptr].valid         <= 1'b1;
                    rob_mem[tail_ptr].ready         <= 1'b0;
                    rob_mem[tail_ptr].pc            <= dispatch_2_rob.pc;
                    rob_mem[tail_ptr].inst          <= dispatch_2_rob.inst;
                    rob_mem[tail_ptr].rd_arch       <= dispatch_2_rob.rd_arch;
                    rob_mem[tail_ptr].rd_phy        <= dispatch_2_rob.rd_phy;
                    rob_mem[tail_ptr].old_phy       <= dispatch_2_rob.old_phy;
                    rob_mem[tail_ptr].rd_we         <= dispatch_2_rob.rd_we;
                    rob_mem[tail_ptr].rs1_val       <= dispatch_2_rob.rs1_val;
                    rob_mem[tail_ptr].rs2_val       <= dispatch_2_rob.rs2_val;
                    rob_mem[tail_ptr].is_store      <= dispatch_2_rob.is_store;
                    rob_mem[tail_ptr].is_load       <= dispatch_2_rob.is_load;
                    rob_mem[tail_ptr].is_branch     <= dispatch_2_rob.is_branch;
                    rob_mem[tail_ptr].is_jump       <= dispatch_2_rob.is_jump;
                    rob_mem[tail_ptr].result        <= '0;
                    rob_mem[tail_ptr].mem_addr      <= '0;
                    rob_mem[tail_ptr].mem_wdata     <= '0;
                    rob_mem[tail_ptr].mem_wmask     <= '0;
                    rob_mem[tail_ptr].branch_taken  <= '0;
                    rob_mem[tail_ptr].branch_target <= '0;
                    rob_mem[tail_ptr].mispredict    <= '0;
                    tail_ptr <= tail_ptr + 1'b1;
                    count    <= count + 1'b1;
                end

                if (commit_ack && !robempty && rob_mem[head_ptr].valid && rob_mem[head_ptr].ready) begin
                    rob_mem[head_ptr] <= '0;
                    head_ptr <= head_ptr + 1'b1;
                    count    <= count - 1'b1;
                end
            end
        end
    end

