            end else begin
                if (commit_ack && (count != 0) && rob_mem[head_ptr].valid && rob_mem[head_ptr].ready) begin
                    rob_mem[head_ptr].valid <= 1'b0;
                    head_ptr <= head_ptr + {{(ROB_IDX_WIDTH-1){1'b0}},1'b1};
                    count <= count - {{ROB_IDX_WIDTH{1'b0}},1'b1};
