                    tail_ptr <= tail_ptr + {{(ROB_IDX_WIDTH-1){1'b0}},1'b1};
                    count <= count + {{ROB_IDX_WIDTH{1'b0}},1'b1};
                end

                if (common_data_bus.valid) begin
                    rob_mem[common_data_bus.rob_idx].ready  <= 1'b1;
