                    rob_q[tail_q].branch_target <= '0;
                    rob_q[tail_q].mispredict    <= 1'b0;
                    rob_q[tail_q].value         <= '0;
                    if (!dispatch_2_rob.regf_we && !dispatch_2_rob.is_store && !dispatch_2_rob.is_branch && !dispatch_2_rob.is_jump)
                        rob_q[tail_q].ready <= 1'b1;
                    tail_q <= tail_q + {{(ROB_IDX_WIDTH-1){1'b0}},1'b1};
                    count_q <= count_q + {{ROB_IDX_WIDTH{1'b0}},1'b1};
                end
            end
        end
    end

    always_comb begin
        rob_idx_dispatch = tail_q;
        robempty = (count_q == '0);
        robfull  = (count_q == ROB_DEPTH);

        rob2commit = '0;
        if (!robempty && rob_q[head_q].valid) begin
            rob2commit.valid         = 1'b1;
            rob2commit.ready         = rob_q[head_q].ready;
            rob2commit.pc            = rob_q[head_q].pc;
            rob2commit.inst          = rob_q[head_q].inst;
            rob2commit.rd_arch       = rob_q[head_q].rd_arch;
            rob2commit.rd_phy        = rob_q[head_q].rd_phy;
            rob2commit.stale_phy     = rob_q[head_q].stale_phy;
            rob2commit.rd_val        = rob_q[head_q].value;
            rob2commit.has_dest      = rob_q[head_q].has_dest;
            rob2commit.is_store      = rob_q[head_q].is_store;
            rob2commit.is_load       = rob_q[head_q].is_load;
            rob2commit.is_branch     = rob_q[head_q].is_branch;
            rob2commit.is_jump       = rob_q[head_q].is_jump;
            rob2commit.branch_taken  = rob_q[head_q].branch_taken;
            rob2commit.branch_target = rob_q[head_q].branch_target;
            rob2commit.mispredict    = rob_q[head_q].mispredict;
            rob2commit.rob_idx       = head_q;
        end

        rob2frlist = '0;
        if (!robempty && rob_q[head_q].valid && commit_ack) begin
            rob2frlist.valid      = rob_q[head_q].has_dest;
            rob2frlist.stale_phy  = rob_q[head_q].stale_phy;
            rob2frlist.commit_phy = rob_q[head_q].rd_phy;
        end
    end

endmodule

module rob
import rv32i_types::*;
(
    input clk, 
    input rst, 
    input dispatch_2_rob_t dispatch_2_rob,  //input from dispatch stage to allocate an entry in rob, 
    input common_data_bus_t common_data_bus,  //input - basically complete signal broadcast to the rob
    input logic commit_ack,    // when rob asks commit stage if the rob head is ready to commit, the commit stage responds back
    output logic [ROB_IDX_WIDTH-1:0] rob_idx_dispatch , // returning the rob index to the dispatch stage after allocation to pass onto next stages
    output logic robfull,                          // sends this is if rob is full 
    output logic robempty,
    output rob2commit_t rob2commit , 

    input lsq2rob_t lsq2robpack , 

    input branchres2rob_t branchres2rob, 
    input branch_flush_t branch_flush, 

    input jumpresrob_t jumpresrob , 

    output rob2frlist_t rob2frlist
); 

  rob_entry_t rob_queue [ROB_SIZE-1:0];  // rob declaration 
  logic [ROB_IDX_WIDTH:0] head; 
  logic [ROB_IDX_WIDTH:0] tail;
  logic [ROB_IDX_WIDTH-1:0] head_index, tail_index;

  assign head_index = head[ROB_IDX_WIDTH-1:0];
  assign tail_index = tail[ROB_IDX_WIDTH-1:0];

  logic empty; 
  assign empty = (head == tail) ? 1'b1 : 1'b0 ; 

  assign robempty = empty; 
  assign robfull = ((head_index == tail_index) && head[ROB_IDX_WIDTH] != tail[ROB_IDX_WIDTH]) ? 1'b1 :1'b0;



  always_ff @(posedge clk) begin
    if(rst) begin
        head <= '0;
        tail <= '0;
    end
    else begin 

        if(commit_ack && !empty) begin 
            head <= head + 1'b1;
            rob_queue[head_index] <= '0;
        end

        if (branch_flush.valid && branch_flush.branch_taken) begin
            if (commit_ack && !empty) begin
                tail <= head + 1'b1;  
            end else begin
                tail <= head;         
           end

            // Clear all entries
            for(integer i = 0; i < ROB_SIZE; i++) begin
                rob_queue[i] <= '0;
            end
        end
        else if(dispatch_2_rob.alloc_en == 1'b1 && !robfull) begin
            rob_queue[tail_index].valid <= 1'b1; 
            rob_queue[tail_index].opcode <= dispatch_2_rob.opcode; 
            rob_queue[tail_index].pc <= dispatch_2_rob.pc; 

            rob_queue[tail_index].branch <= dispatch_2_rob.branch;
            rob_queue[tail_index].branch_taken <= dispatch_2_rob.branch_taken ; 
            rob_queue[tail_index].branchtg_addr <= dispatch_2_rob.branchtg_addr ; 

            rob_queue[tail_index].jump <= dispatch_2_rob.jump ; 

            rob_queue[tail_index].exception <= 1'b0;
            rob_queue[tail_index].arf_rs1 <= dispatch_2_rob.arf_rs1;
            rob_queue[tail_index].arf_rs2 <= dispatch_2_rob.arf_rs2;
            rob_queue[tail_index].instruction <= dispatch_2_rob.instruction;

            rob_queue[tail_index].is_load <= dispatch_2_rob.is_load;
            rob_queue[tail_index].is_store <= dispatch_2_rob.is_store;

            rob_queue[tail_index].dmem_addr <= dispatch_2_rob.dmem_addr;
            rob_queue[tail_index].dmem_rmask <= dispatch_2_rob.dmem_rmask;
            rob_queue[tail_index].dmem_wmask <= dispatch_2_rob.dmem_wmask;
            rob_queue[tail_index].dmem_wdata <= dispatch_2_rob.dmem_wdata;

            rob_queue[tail_index].branchfrlist_checpt <= dispatch_2_rob.freelist_head_checkpoint; // useful when restoring free for mispredict
            rob_queue[tail_index].branchtail_checpt <= dispatch_2_rob.freelist_tail_checkpoint;

            rob_queue[tail_index].freelistcount <= dispatch_2_rob.freelistcount ; 

            tail <= tail + 1'b1;

            if((dispatch_2_rob.has_rd_check == 1'b1) ) begin
                rob_queue[tail_index].has_rd <= 1'b1; 
                rob_queue[tail_index].arf_rd <= dispatch_2_rob.arf_rd; 
                rob_queue[tail_index].old_phy_rd <= dispatch_2_rob.old_phy_rd; 
                rob_queue[tail_index].new_phy_rd <= dispatch_2_rob.new_phy_rd;
                rob_queue[tail_index].ready2commit <= 1'b0;  // Wait for CDB
            end else begin
                rob_queue[tail_index].has_rd <= 1'b0;
                rob_queue[tail_index].arf_rd <= '0;
                rob_queue[tail_index].old_phy_rd <= '0;
                rob_queue[tail_index].new_phy_rd <= '0;
                if(dispatch_2_rob.branch || dispatch_2_rob.is_store || dispatch_2_rob.jump) begin 
                    rob_queue[tail_index].ready2commit <= 1'b0;
                end else begin 
                    rob_queue[tail_index].ready2commit <= 1'b1;
                end

            end
        end

        if(common_data_bus.complete && !empty) begin
            rob_queue[common_data_bus.rob_idx].ready2commit <= 1'b1;
        end

        // update a load/store rob entry
        if(lsq2robpack.valid) begin 

            if(lsq2robpack.is_load) begin  
                rob_queue[lsq2robpack.rob_idx].is_load <= lsq2robpack.is_load;
                rob_queue[lsq2robpack.rob_idx].dmem_addr <= lsq2robpack.dmem_addr;
                rob_queue[lsq2robpack.rob_idx].dmem_rmask <= lsq2robpack.dmem_rmask;

            end else if(lsq2robpack.is_store) begin  
                rob_queue[lsq2robpack.rob_idx].is_store <= lsq2robpack.is_store;
                rob_queue[lsq2robpack.rob_idx].dmem_addr <= lsq2robpack.dmem_addr;
                rob_queue[lsq2robpack.rob_idx].dmem_wmask <= lsq2robpack.dmem_wmask;
                rob_queue[lsq2robpack.rob_idx].dmem_wdata <= lsq2robpack.dmem_wdata;
                rob_queue[lsq2robpack.rob_idx].ready2commit <= 1'b1;
            end
        end

        // branch resolution check 
        if(branchres2rob.valid && rob_queue[branchres2rob.rob_idx].branch) begin 
            if(branchres2rob.cmp_result == 1'b1) begin // set as branch taken
                rob_queue[branchres2rob.rob_idx].branch_taken <= 1'b1 ; 
            end
            rob_queue[branchres2rob.rob_idx].ready2commit <= 1'b1;
        end

        if(jumpresrob.valid) begin 
            // For jumps, the ROB must hold the resolved control-flow target.
            // JAL target is already known at dispatch, but JALR target depends on rs1.
            // Update the ROB entry with rs1 + imm, then clear bit 0 per ISA.
            if(jumpresrob.jalr) begin 
                rob_queue[jumpresrob.rob_idx].branchtg_addr <= (rob_queue[jumpresrob.rob_idx].branchtg_addr + jumpresrob.rs1) & 32'hFFFFFFFE;
            end
        end
    end 
end

assign rob_idx_dispatch = tail_index;

  // active logic - feeding the commit stage with the rob head entry info
  always_comb begin
    rob2commit.rob_head_idx = head_index ; 
    rob2commit.commit = rob_queue[head_index].ready2commit ;
    rob2commit.pc = rob_queue[head_index].pc ;
    rob2commit.has_rd = rob_queue[head_index].has_rd ;
    rob2commit.arf_rd = rob_queue[head_index]. arf_rd ;
    rob2commit.new_phy_rd = rob_queue[head_index].new_phy_rd ;
    rob2commit.old_phy_rd = rob_queue[head_index].old_phy_rd ;
    rob2commit.arf_rs1 = rob_queue[head_index].arf_rs1 ;
    rob2commit.arf_rs2 = rob_queue[head_index].arf_rs2 ;


    rob2commit.jump = rob_queue[head_index].jump ; 

    rob2commit.branch = rob_queue[head_index].branch ; 
    rob2commit.branch_taken = rob_queue[head_index].branch_taken ; 
    rob2commit.branchtg_addr  = rob_queue[head_index].branchtg_addr ; 


    rob2commit.is_load = rob_queue[head_index].is_load ; 
    rob2commit.is_store = rob_queue[head_index].is_store ; 
    rob2commit.dmem_addr = rob_queue[head_index].dmem_addr ;
    rob2commit.dmem_rmask = rob_queue[head_index].dmem_rmask ; 
    rob2commit.dmem_wmask = rob_queue[head_index].dmem_wmask ;  
    rob2commit.dmem_wdata = rob_queue[head_index].dmem_wdata ; 

    rob2commit.instruction = rob_queue[head_index].instruction ;


    rob2frlist.valid = branch_flush.valid && branch_flush.branch_taken;

    rob2frlist.freelist_head = rob_queue[head_index].branchfrlist_checpt ; 
    rob2frlist.freelist_tail = rob_queue[head_index].branchtail_checpt ; 

    rob2frlist.freelistcount = rob_queue[head_index].freelistcount ; 

    rob2frlist.jump_flush = rob_queue[head_index].jump ; 
  end

endmodule: rob

module execute 
import rv32i_types::*;
(
    input logic clk,
    input logic rst,
    input issue2execute_t issue2execute,

    output execute2memory_t execute2mem,

    output branchres2rob_t branchres2rob, 

    output jumpresrob_t jumpresrob, 


    output logic execute_stall, 
    input logic mem_stall, 

    input branch_flush_t branch_flush 
);

logic route_to_alu;
logic route_to_mul;
logic route_to_div;
logic route_to_cmp;
logic route_to_agu ; 

logic signed [63:0] mul_ss, mul_su;
logic        [63:0] mul_uu;

always_comb begin
    route_to_alu = '0;
    route_to_div = '0;
    route_to_mul = '0;
    route_to_cmp = '0;
    route_to_agu = '0 ; 

    if (issue2execute.rs_type == 3'b001) begin
        route_to_mul = '1;
    end else if (issue2execute.rs_type == 3'b010) begin
        route_to_div = '1;
    end else if (issue2execute.rs_type == 3'b011)  begin
        route_to_alu = '1;
    end else if (issue2execute.rs_type == 3'b100) begin
        route_to_cmp = '1;
    end else if (issue2execute.rs_type == 3'b101) begin
        route_to_agu = '1;
    end
end

logic [2:0] aluop;
logic [31:0] alu_a, alu_b;
logic [31:0] alu_result;
logic [31:0] alu_final_result;
logic [31:0] jump_target;

always_comb begin
    jumpresrob = '0 ; 
    alu_a = issue2execute.phy_src1_v;
    jump_target = '0;

    if(issue2execute.issued_entry.is_jump) begin 
        jumpresrob.valid = 1'b1 ; 
        jumpresrob.rob_idx = issue2execute.issued_entry.rob_idx ; 

        if(issue2execute.issued_entry.opcode == 7'b1100111) begin 
            jumpresrob.jalr = 1'b1 ; 
            jumpresrob.rs1 = issue2execute.phy_src1_v ; 
            jump_target = issue2execute.phy_src1_v + issue2execute.issued_entry.imm;
        end else begin 
            jumpresrob.jal = 1'b1 ; 
            jumpresrob.rs1 = '0 ; 
            jump_target = issue2execute.issued_entry.pc + issue2execute.issued_entry.imm;
        end

        alu_a = issue2execute.issued_entry.pc;
    end

    if (issue2execute.issued_entry.has_imm && !(issue2execute.issued_entry.is_jump) ) begin
        alu_b = issue2execute.issued_entry.imm;
    end else if(issue2execute.issued_entry.is_jump) begin 
        alu_b = 32'd4 ;
    end else begin
        alu_b = issue2execute.phy_src2_v;
    end
end

always_comb begin
    aluop = alu_add;

    case (issue2execute.issued_entry.opcode)
        op_lui, op_auipc, op_jal, op_jalr: begin
            aluop = alu_add; 
        end
        op_imm, op_reg: begin
            case (issue2execute.issued_entry.funct3)
                3'b000: begin
                    if (issue2execute.issued_entry.opcode == op_reg && issue2execute.issued_entry.funct7[5]) begin
                        aluop = alu_sub;
                    end else begin
                        aluop = alu_add;
                    end
                end
                3'b001: aluop = alu_sll;
                3'b100: aluop = alu_xor;
                3'b101: begin
                    if (issue2execute.issued_entry.funct7[5]) begin
                        aluop = alu_sra;
                    end else begin
                        aluop = alu_srl;
                    end
                end
                3'b110: aluop = alu_or;
                3'b111: aluop = alu_and;
                default: aluop = alu_add;
            endcase
        end
        default: aluop = alu_add;
    endcase
end

alu alu_inst (
    .aluop(aluop),
    .a(alu_a),
    .b(alu_b),
    .aluout(alu_result)
);

always_comb begin
    case (issue2execute.issued_entry.opcode)
        op_lui, op_auipc: alu_final_result = issue2execute.issued_entry.imm;
        default: alu_final_result = alu_result;
    endcase
end

logic [31:0] agu_a, agu_b;
logic [31:0] agu_result;
logic [31:0] agu_final_result;

always_comb begin
    agu_a = issue2execute.phy_src1_v;
    agu_b = issue2execute.issued_entry.imm;
end

alu agu_inst (
    .aluop(alu_add),
    .a(agu_a),
    .b(agu_b),
    .aluout(agu_result)
);

assign agu_final_result = agu_result ; 

logic [1:0]addr_offset;
logic [31:0] sb_data, sh_data;
assign addr_offset = agu_result[1:0];

always_comb begin
    execute2mem.agu_result.result = '0;
    execute2mem.agu_result.is_load = '0;
    execute2mem.agu_result.is_store = '0;
    execute2mem.agu_result.dmem_wmask = '0;
    execute2mem.agu_result.dmem_rmask = '0;
    execute2mem.agu_result.dmem_wdata = '0;
    execute2mem.agu_result.dmem_rdata = '0;
    execute2mem.agu_result.store_commited = '0;
    execute2mem.agu_result.phy_rd = issue2execute.issued_entry.phy_dest;
    execute2mem.agu_result.result_ready = route_to_agu;
    execute2mem.agu_result.rob_idx = issue2execute.issued_entry.rob_idx;
    execute2mem.agu_result.has_rd = '0 ; 
    execute2mem.agu_result.loadunsigned = ((issue2execute.issued_entry.funct3 == 3'b101) || (issue2execute.issued_entry.funct3 == 3'b100)) ; 
    sb_data = '0;
    sh_data = '0;

    if (issue2execute.issued_entry.opcode == op_load) begin
        execute2mem.agu_result.is_load = '1;
        execute2mem.agu_result.has_rd = '1;
        execute2mem.agu_result.result = agu_result;
        case (issue2execute.issued_entry.funct3) 
            lw: execute2mem.agu_result.dmem_rmask = 4'b1111;
            lh,lhu: execute2mem.agu_result.dmem_rmask = addr_offset[1] ? 4'b1100 : 4'b0011;
            lb, lbu : begin
                if (addr_offset == 2'b00) begin
                    execute2mem.agu_result.dmem_rmask = 4'b0001;
                end else if (addr_offset == 2'b01) begin
                    execute2mem.agu_result.dmem_rmask = 4'b0010;
                end else if (addr_offset == 2'b10) begin
                    execute2mem.agu_result.dmem_rmask = 4'b0100;
                end else begin
                    execute2mem.agu_result.dmem_rmask = 4'b1000;
                end
            end
            default: execute2mem.agu_result.dmem_rmask = 4'b0000;
        endcase
    end

    if (issue2execute.issued_entry.opcode == op_store) begin
        unique case (addr_offset)
            2'b00: sb_data = {24'b0, issue2execute.phy_src2_v[7:0]};
            2'b01: sb_data = {16'b0, issue2execute.phy_src2_v[7:0], 8'b0};
            2'b10: sb_data = {8'b0, issue2execute.phy_src2_v[7:0], 16'b0};
            2'b11: sb_data = {issue2execute.phy_src2_v[7:0], 24'b0};
        endcase

        sh_data = addr_offset[1] ? {issue2execute.phy_src2_v[15:0], 16'b0} : {16'b0, issue2execute.phy_src2_v[15:0]};

        execute2mem.agu_result.is_store = '1;
        execute2mem.agu_result.has_rd = '0;
        execute2mem.agu_result.result = agu_result;

        case (issue2execute.issued_entry.funct3)
            sw: begin
                execute2mem.agu_result.dmem_wmask = 4'b1111;
                execute2mem.agu_result.dmem_wdata = issue2execute.phy_src2_v;
            end
            sh: begin 
                execute2mem.agu_result.dmem_wmask = addr_offset[1] ? 4'b1100 : 4'b0011;
                execute2mem.agu_result.dmem_wdata = sh_data;
            end
            sb: begin 
                execute2mem.agu_result.dmem_wdata = sb_data;
                if (addr_offset == 2'b00) begin
                    execute2mem.agu_result.dmem_wmask = 4'b0001;
                end else if (addr_offset == 2'b01) begin
                    execute2mem.agu_result.dmem_wmask = 4'b0010;
                end else if (addr_offset == 2'b10) begin
                    execute2mem.agu_result.dmem_wmask = 4'b0100;
                end else begin
                    execute2mem.agu_result.dmem_wmask = 4'b1000;
                end
            end
            default: begin
                execute2mem.agu_result.dmem_wmask = 4'b0000;
                execute2mem.agu_result.dmem_wdata = '0;
            end
        endcase
    end
end

logic [2:0] cmpop;
logic cmpout;
logic [31:0] cmp_result;
logic [31:0] cmp_a, cmp_b;

always_comb begin
    cmp_a = issue2execute.phy_src1_v;
    if (issue2execute.issued_entry.has_imm && !(issue2execute.issued_entry.is_branch)) begin
        cmp_b = issue2execute.issued_entry.imm;
    end else begin
        cmp_b = issue2execute.phy_src2_v;
    end
end

always_comb begin
    cmpop = beq;

    if (issue2execute.issued_entry.opcode == op_br) begin
        cmpop = issue2execute.issued_entry.funct3;
    end else if ((issue2execute.issued_entry.opcode == op_imm ||  issue2execute.issued_entry.opcode == op_reg) &&  (issue2execute.issued_entry.funct3 == 3'b010 ||  issue2execute.issued_entry.funct3 == 3'b011)) begin
        if (issue2execute.issued_entry.funct3 == 3'b010) begin
            cmpop = blt;
        end else begin
            cmpop = bltu;
        end
    end
end

cmp cmp_inst (
    .cmpop(cmpop),
    .a(cmp_a),
    .b(cmp_b),
    .cmpout(cmpout)
);

assign cmp_result = {31'b0, cmpout};

logic [ROB_IDX_WIDTH-1:0]rob_idx_q;

always_ff @(posedge clk) begin
    if (rst) begin
        rob_idx_q <= '0;
    end else begin
        rob_idx_q <= issue2execute.issued_entry.rob_idx;
    end
end

always_ff @(posedge clk) begin
    if (rst) begin
        execute2mem.alu_result <= '0;
        execute2mem.cmp_result <= '0;
        branchres2rob <= '0 ; 
    end else if (branch_flush.valid && branch_flush.branch_taken) begin
        branchres2rob <= '0;
        execute2mem.alu_result <= '0;
        execute2mem.cmp_result <= '0;
    end else begin
        execute2mem.alu_result.result_ready <= route_to_alu;
        execute2mem.alu_result.result <= alu_final_result;
        execute2mem.alu_result.phy_rd <= issue2execute.issued_entry.phy_dest;
        execute2mem.alu_result.rob_idx <= issue2execute.issued_entry.rob_idx;
        execute2mem.alu_result.has_rd <= issue2execute.issued_entry.has_rd;
        execute2mem.alu_result.is_load <= '0;
        execute2mem.alu_result.is_store <= '0;
        execute2mem.alu_result.store_commited <= '0;
        execute2mem.alu_result.dmem_rdata <= '0;
        execute2mem.alu_result.dmem_rmask <= '0;
        execute2mem.alu_result.dmem_wmask <= '0;
        execute2mem.alu_result.dmem_wdata <= '0;
        execute2mem.alu_result.loadunsigned <= '0;

        execute2mem.cmp_result.result_ready <= route_to_cmp;
        execute2mem.cmp_result.result <= cmp_result;
        execute2mem.cmp_result.phy_rd <= issue2execute.issued_entry.phy_dest;
        execute2mem.cmp_result.rob_idx <= issue2execute.issued_entry.rob_idx;
        execute2mem.cmp_result.has_rd <= issue2execute.issued_entry.has_rd;
        execute2mem.cmp_result.is_load <= '0;
        execute2mem.cmp_result.is_store <= '0;
        execute2mem.cmp_result.store_commited <= '0;
        execute2mem.cmp_result.dmem_rdata <= '0;
        execute2mem.cmp_result.dmem_rmask <= '0;
        execute2mem.cmp_result.dmem_wmask <= '0;
        execute2mem.cmp_result.dmem_wdata <= '0;
        execute2mem.cmp_result.loadunsigned <= '0;

        branchres2rob <= '0;
        if (issue2execute.issued_entry.is_branch) begin
            branchres2rob.valid <= route_to_cmp;
            branchres2rob.rob_idx <= issue2execute.issued_entry.rob_idx;
            branchres2rob.cmp_result <= cmpout;
        end
    end
end

assign execute_stall = mem_stall;

endmodule

module rob
import rv32i_types::*;
(
    input clk, 
    input rst, 
    input dispatch_2_rob_t dispatch_2_rob,  //input from dispatch stage to allocate an entry in rob, 
    input common_data_bus_t common_data_bus,  //input - basically complete signal broadcast to the rob
    input logic commit_ack,    // when rob asks commit stage if the rob head is ready to commit, the commit stage responds back
    output logic [ROB_IDX_WIDTH-1:0] rob_idx_dispatch , // returning the rob index to the dispatch stage after allocation to pass onto next stages
    output logic robfull,                          // sends this is if rob is full 
    output logic robempty,
    output rob2commit_t rob2commit , 

    input lsq2rob_t lsq2robpack , 

    input branchres2rob_t branchres2rob, 
    input branch_flush_t branch_flush, 

    input jumpresrob_t jumpresrob , 

